/* ===== クリスマスのオーナメント 150種（3D） =====
   すべて「ボールの半径 = 1」の大きさで作り、最後に同じ大きさにそろえる。正面は +z。 */
import * as THREE from 'three';
import { RoundedBoxGeometry } from './vendor/three/RoundedBoxGeometry.js';
import { RoomEnvironment } from './vendor/three/RoomEnvironment.js';

const V = (x, y, z = 0) => new THREE.Vector3(x, y, z);
const TAU = Math.PI * 2;

/* ---------- テクスチャ ---------- */
const texCache = new Map();
function tex(key, w, h, draw, rep = [1, 1]){
  const k = key + '|' + rep; if (texCache.has(k)) return texCache.get(k);
  const c = document.createElement('canvas'); c.width = w; c.height = h; const g = c.getContext('2d'); draw(g, w, h);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(...rep); t.anisotropy = 4;
  texCache.set(k, t); return t;
}
let seed = 1; const R = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
// 球に貼る柄（正距円筒。極に近いほど横に伸ばして、丸く見せる）
function sphereDots(bg, fg, n = 9){ return tex('sd' + bg + fg + n, 512, 256, (g, w, h) => { g.fillStyle = bg; g.fillRect(0, 0, w, h); g.fillStyle = fg;
  for (let row = 1; row < n; row++){ const y = row / n * h, lat = (y / h - .5) * Math.PI, k = 1 / Math.max(.25, Math.cos(lat)), cnt = Math.max(3, Math.round(n * 2 * Math.cos(lat)));
    for (let q = 0; q < cnt; q++){ const x = (q + (row % 2) * .5) / cnt * w; g.beginPath(); g.ellipse(x, y, 9 * k, 9, 0, 0, TAU); g.fill(); g.beginPath(); g.ellipse(x + w, y, 9 * k, 9, 0, 0, TAU); g.fill(); } } }); }
function sphereStripes(bg, fg){ return tex('ss' + bg + fg, 512, 256, (g, w, h) => { g.fillStyle = bg; g.fillRect(0, 0, w, h); g.fillStyle = fg;
  for (let i = -8; i < 24; i++){ g.beginPath(); g.moveTo(i * 32, 0); g.lineTo(i * 32 + 14, 0); g.lineTo(i * 32 + 14 + h * .55, h); g.lineTo(i * 32 + h * .55, h); g.fill(); } }); }
function sphereBands(bg, fg, n = 6){ return tex('sb' + bg + fg + n, 256, 256, (g, w, h) => { g.fillStyle = bg; g.fillRect(0, 0, w, h); g.fillStyle = fg; for (let i = 1; i < n; i++) g.fillRect(0, i / n * h - 7, w, 14); }); }
function flakeAt(g, x, y, r, col, lw){ g.strokeStyle = col; g.lineWidth = lw; g.lineCap = 'round'; for (let a = 0; a < 3; a++){ g.save(); g.translate(x, y); g.rotate(a * Math.PI / 3); g.beginPath(); g.moveTo(0, -r); g.lineTo(0, r);
  for (const s of [-1, 1]){ g.moveTo(0, s * r * .55); g.lineTo(-r * .3, s * r * .8); g.moveTo(0, s * r * .55); g.lineTo(r * .3, s * r * .8); } g.stroke(); g.restore(); } }
function sphereSnow(bg, fg){ return tex('sn' + bg + fg, 512, 256, (g, w, h) => { g.fillStyle = bg; g.fillRect(0, 0, w, h); seed = 7;
  for (let row = 1; row < 5; row++){ const y = row / 5 * h, lat = (y / h - .5) * Math.PI, cnt = Math.max(3, Math.round(9 * Math.cos(lat))); for (let q = 0; q < cnt; q++){ const x = (q + (row % 2) * .5) / cnt * w; g.save(); g.translate(x, y); g.scale(1 / Math.max(.3, Math.cos(lat)), 1); flakeAt(g, 0, 0, 16 + R() * 6, fg, 3.4); g.restore(); } } }); }
function sphereGlitter(bg){ return tex('sg' + bg, 512, 256, (g, w, h) => { g.fillStyle = bg; g.fillRect(0, 0, w, h); seed = 11;
  for (let i = 0; i < 2600; i++){ const x = R() * w, y = R() * h, r = R() < .9 ? 1 + R() * 1.6 : 2.6; g.fillStyle = ['rgba(255,255,255,.9)', 'rgba(255,236,170,.85)', 'rgba(255,255,255,.5)', 'rgba(0,0,0,.18)'][Math.floor(R() * 4)]; g.beginPath(); g.ellipse(x, y, r / Math.max(.3, Math.cos((y / h - .5) * Math.PI)), r, 0, 0, TAU); g.fill(); } }); }
const feltTex = () => tex('felt', 256, 256, (g, w, h) => { g.fillStyle = '#fff'; g.fillRect(0, 0, w, h); seed = 5; for (let i = 0; i < 9000; i++){ const v = 200 + R() * 55 | 0; g.fillStyle = `rgb(${v},${v},${v})`; g.fillRect(R() * w, R() * h, 1.5, 1.5); } }, [2, 2]);
const woodTex = (c) => tex('wood' + c, 256, 256, (g, w, h) => { g.fillStyle = c; g.fillRect(0, 0, w, h); seed = 3; for (let i = 0; i < 40; i++){ g.strokeStyle = `rgba(90,50,20,${.1 + R() * .18})`; g.lineWidth = 1 + R() * 2.4; g.beginPath(); const y = R() * h; g.moveTo(0, y); for (let x = 0; x <= w; x += 16) g.lineTo(x, y + Math.sin(x / 30 + i) * 4); g.stroke(); } });
const knitTex = (c) => tex('knit' + c, 128, 128, (g, w, h) => { g.fillStyle = c; g.fillRect(0, 0, w, h); for (let x = 0; x < w; x += 16) for (let y = 0; y < h; y += 12){ g.fillStyle = 'rgba(255,255,255,.18)'; g.beginPath(); g.ellipse(x + 4, y + 6, 3.4, 6, .5, 0, TAU); g.fill(); g.beginPath(); g.ellipse(x + 12, y + 6, 3.4, 6, -.5, 0, TAU); g.fill(); } }, [4, 2]);
const candyTex = (a, b) => tex('cand' + a + b, 128, 128, (g, w, h) => { g.fillStyle = a; g.fillRect(0, 0, w, h); g.fillStyle = b; for (let i = -4; i < 8; i++){ g.beginPath(); g.moveTo(i * 32, 0); g.lineTo(i * 32 + 14, 0); g.lineTo(i * 32 + 14 + h, h); g.lineTo(i * 32 + h, h); g.fill(); } });
const spiralTex = (a, b) => tex('spir' + a + b, 256, 256, (g, w, h) => { g.fillStyle = a; g.fillRect(0, 0, w, h); g.strokeStyle = b; g.lineWidth = 16; g.lineCap = 'round'; g.beginPath(); for (let t = 0; t < 26; t += .05){ const r = t * 4.6, x = w / 2 + Math.cos(t) * r, y = h / 2 + Math.sin(t) * r; t ? g.lineTo(x, y) : g.moveTo(x, y); } g.stroke(); });
const barkTex = () => tex('bark', 256, 128, (g, w, h) => { g.fillStyle = '#6a3a1e'; g.fillRect(0, 0, w, h); seed = 9; for (let i = 0; i < 70; i++){ g.strokeStyle = `rgba(${R() < .5 ? '40,18,6' : '150,96,58'},.6)`; g.lineWidth = 2 + R() * 3; g.beginPath(); const y = R() * h; g.moveTo(0, y); for (let x = 0; x <= w; x += 20) g.lineTo(x, y + (R() - .5) * 8); g.stroke(); } });
const zigTex = () => tex('zig', 256, 64, (g, w, h) => { g.fillStyle = '#c8352e'; g.fillRect(0, 0, w, h); g.strokeStyle = '#f2c14e'; g.lineWidth = 6; g.beginPath(); for (let i = 0; i <= 8; i++) g.lineTo(i * w / 8, i % 2 ? h * .82 : h * .18); g.stroke(); });
const saturnTex = () => tex('sat', 256, 128, (g, w, h) => { const c = ['#f0b878', '#e8a060', '#f6cc94', '#d88a50', '#f0b878', '#e89a5a']; for (let i = 0; i < 12; i++){ g.fillStyle = c[i % c.length]; g.fillRect(0, i / 12 * h, w, h / 12 + 1); } });

/* ---------- 素材 ---------- */
const matCache = new Map();
function mc(key, make){ if (!matCache.has(key)) matCache.set(key, make()); return matCache.get(key); }
const gloss = (c, map) => mc('gl' + c + (map ? map.uuid : ''), () => new THREE.MeshPhysicalMaterial({ color:map ? '#ffffff' : c, map:map || null, roughness:.24, metalness:.05, clearcoat:.8, clearcoatRoughness:.12 }));
const matte = (c, o = {}) => mc('mt' + c + JSON.stringify(o), () => new THREE.MeshStandardMaterial({ color:c, roughness:.7, metalness:0, ...o }));
const GOLD = () => mc('gold', () => new THREE.MeshStandardMaterial({ color:'#f4c24a', roughness:.32, metalness:.6, envMapIntensity:2.2, emissive:'#4a2c04', emissiveIntensity:.35 }));
const SILVER = () => mc('silver', () => new THREE.MeshStandardMaterial({ color:'#e8ecf2', roughness:.26, metalness:.6, envMapIntensity:2.2 }));
const metalC = (c) => mc('mc' + c, () => new THREE.MeshStandardMaterial({ color:c, roughness:.3, metalness:.6, envMapIntensity:2.2 }));
const felt = (c) => mc('fe' + c, () => new THREE.MeshPhysicalMaterial({ color:c, map:feltTex(), roughness:1, metalness:0, sheen:1, sheenRoughness:.7, sheenColor:new THREE.Color('#ffffff') }));
const glass = (c) => mc('gs' + c, () => new THREE.MeshPhysicalMaterial({ color:c, roughness:.06, metalness:0, transparent:true, opacity:.72, clearcoat:1, clearcoatRoughness:.04, side:THREE.DoubleSide, depthWrite:false }));
const glow = (c, k = 1.6) => mc('em' + c + k, () => new THREE.MeshStandardMaterial({ color:c, emissive:c, emissiveIntensity:k, roughness:.5 }));
const wood = (c = '#d2a06a') => mc('wd' + c, () => new THREE.MeshStandardMaterial({ color:'#ffffff', map:woodTex(c), roughness:.75 }));
const BLACK = () => mc('blk', () => new THREE.MeshPhysicalMaterial({ color:'#1e1a1c', roughness:.2, clearcoat:1 }));

/* ---------- 形の部品 ---------- */
function add(g, geo, mat, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0, sx = 1, sy = sx, sz = sx){ const m = new THREE.Mesh(geo, mat); m.position.set(x, y, z); m.rotation.set(rx, ry, rz); m.scale.set(sx, sy, sz); m.castShadow = true; g.add(m); return m; }
const sph = (r = 1, ws = 32, hs = 24, ...rest) => new THREE.SphereGeometry(r, ws, hs, ...rest);
const cyl = (rt, rb, h, s = 32) => new THREE.CylinderGeometry(rt, rb, h, s);
const tor = (R0, r, rs = 14, ts = 40, arc = TAU) => new THREE.TorusGeometry(R0, r, rs, ts, arc);
const rbox = (w, h, d, r = .08) => new RoundedBoxGeometry(w, h, d, 3, Math.min(r, w / 2 - .001, h / 2 - .001, d / 2 - .001));
const cone = (r, h, s = 32) => new THREE.ConeGeometry(r, h, s);
function lathe(pts, segs = 48, rows = 0){ let v = pts.map(([r, y]) => new THREE.Vector2(Math.max(.0005, r), y)); if (rows){ const c = new THREE.SplineCurve(v); v = c.getSpacedPoints(rows).map(p => new THREE.Vector2(Math.max(.0005, p.x), p.y)); } return new THREE.LatheGeometry(v, segs); }
function tube(pts, r, segs = 64, closed = false, rs = 12){ return new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts.map(p => V(...p)), closed), segs, r, rs, closed); }
function ext(shape, depth = .3, bevel = .08, seg = 3){ const g = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled:true, bevelThickness:bevel, bevelSize:bevel, bevelSegments:seg, curveSegments:24 }); g.translate(0, 0, -depth / 2); return g; }
// 平面の UV を形の外接に合わせる（押し出し形に柄を貼るため）
function planarUV(geo, sx = 1, sy = 1){ geo.computeBoundingBox(); const b = geo.boundingBox, p = geo.attributes.position, uv = geo.attributes.uv; for (let i = 0; i < p.count; i++) uv.setXY(i, (p.getX(i) - b.min.x) / (b.max.x - b.min.x) * sx, (p.getY(i) - b.min.y) / (b.max.y - b.min.y) * sy); return geo; }
// 形
function shStar(n = 5, ro = 1, ri = .45){ const s = new THREE.Shape(); for (let i = 0; i < n * 2; i++){ const a = Math.PI / 2 + i * Math.PI / n, r = i % 2 ? ri : ro; i ? s.lineTo(Math.cos(a) * r, Math.sin(a) * r) : s.moveTo(Math.cos(a) * r, Math.sin(a) * r); } s.closePath(); return s; }
function shHeart(k = 1){ const s = new THREE.Shape(); s.moveTo(0, -1 * k); s.bezierCurveTo(-.55 * k, -.55 * k, -1.15 * k, -.1 * k, -1.05 * k, .38 * k); s.bezierCurveTo(-.95 * k, .92 * k, -.25 * k, 1.02 * k, 0, .52 * k); s.bezierCurveTo(.25 * k, 1.02 * k, .95 * k, .92 * k, 1.05 * k, .38 * k); s.bezierCurveTo(1.15 * k, -.1 * k, .55 * k, -.55 * k, 0, -1 * k); return s; }
function shPath(pts, smooth = true){ const s = new THREE.Shape(); if (smooth){ s.setFromPoints(new THREE.SplineCurve(pts.map(p => new THREE.Vector2(...p)).concat([new THREE.Vector2(...pts[0])])).getPoints(120)); } else { s.moveTo(...pts[0]); pts.slice(1).forEach(p => s.lineTo(...p)); s.closePath(); } return s; }

/* ---------- 金具 ---------- */
let NOHANG = false;
function cap(g, y = 1, s = 1){ if (NOHANG){ g.userData.hangY = y; return; } add(g, cyl(.27 * s, .3 * s, .26 * s, 24), GOLD(), 0, y + .06 * s); for (let i = 0; i < 10; i++){ const a = i / 10 * TAU; add(g, cyl(.018 * s, .018 * s, .24 * s, 6), metalC('#b88a2a'), Math.sin(a) * .29 * s, y + .06 * s, Math.cos(a) * .29 * s); }
  add(g, tor(.2 * s, .05 * s, 10, 24), GOLD(), 0, y + .36 * s, 0, 0, Math.PI / 2); g.userData.hangY = y + .55 * s; }
function ring(g, y = 1, s = 1){ if (NOHANG){ g.userData.hangY = y; return; } add(g, tor(.17 * s, .045 * s, 10, 24), GOLD(), 0, y + .14 * s, 0, 0, Math.PI / 2); add(g, cyl(.035 * s, .035 * s, .12 * s, 8), GOLD(), 0, y - .02 * s); g.userData.hangY = y + .3 * s; }
// 柔らかい糸で下げるもの（フェルト、おかしなど）
function thread(g, y = 1, s = 1){ if (NOHANG){ g.userData.hangY = y; return; } add(g, tube([[0, y - .05, 0], [.03, y + .2, 0], [0, y + .42, 0]], .03 * s, 12, false, 6), matte('#e8d8b0', { roughness:.9 })); add(g, tor(.13 * s, .035 * s, 8, 20), matte('#e8d8b0', { roughness:.9 }), 0, y + .52 * s, 0, 0, Math.PI / 2); g.userData.hangY = y + .65 * s; }
const eye = (g, x, y, z, r = .09) => { add(g, sph(r, 16, 12), BLACK(), x, y, z); add(g, sph(r * .32, 8, 6), matte('#ffffff', { roughness:.2 }), x - r * .3, y + r * .35, z + r * .82); };
const cheek = (g, x, y, z, r = .13) => add(g, sph(r, 16, 10), matte('#f4a0a8', { roughness:.9 }), x, y, z, 0, 0, 0, 1, .6, .35);
function bow(g, c, x, y, z, s = 1, rz = 0){ const m = matte(c, { roughness:.45 }); const b = new THREE.Group(); b.position.set(x, y, z); b.rotation.z = rz; b.scale.setScalar(s); g.add(b);
  for (const sd of [-1, 1]){ add(b, tor(.22, .085, 10, 24), m, sd * .24, .02, 0, 0, 0, sd * .35, 1.15, .9, .7); add(b, rbox(.12, .42, .06, .03), m, sd * .14, -.28, 0, 0, 0, sd * .35); } add(b, sph(.11, 16, 12), m, 0, 0, .02); return b; }

/* ---------- ボール ---------- */
function ball(color, map, opt = {}){ const g = new THREE.Group(); add(g, sph(1, 48, 32), opt.metal ? metalC(color) : opt.glass ? glass(color) : gloss(color, map)); if (opt.glass) add(g, sph(.55, 24, 16), glow('#ffffff', .15), .1, -.1, 0);
  if (opt.band) { add(g, tor(1.0, .09, 12, 64), GOLD(), 0, 0, 0, Math.PI / 2); for (let i = 0; i < 16; i++){ const a = i / 16 * TAU; add(g, sph(.09, 12, 8), matte('#fbf6ec', { roughness:.25 }), Math.sin(a) * 1.07, 0, Math.cos(a) * 1.07); } }
  cap(g, .98); g.rotation.z = -.12; return g; }
const BC = [['ピンク', '#f08aa8'], ['水色', '#7cc0e4'], ['むらさき', '#9a72c8'], ['白', '#f2f0ea'], ['黒', '#3a3a44'], ['ボルドー', '#8a2a3a'], ['ミント', '#7ccab0'], ['オレンジ', '#f0943a']];
const ballPat = [
  c => ball(c, sphereDots(c, c === '#f2f0ea' ? '#d8303a' : '#ffffff')),
  c => ball(c, sphereStripes(c, c === '#f2f0ea' ? '#3a8a5a' : '#ffffff')),
  c => ball(c, sphereSnow(c, c === '#f2f0ea' ? '#6aa8d8' : '#ffffff')),
  c => ball(c, sphereGlitter(c)),
  c => ball(c, null, { band:true }),
];

/* ---------- ガラス ---------- */
const GC = ['#e04a5a', '#e8b84a', '#8ec8ec', '#5aac7a', '#a682d8', '#f4a0c0'];
function twisted(geo, k, lobes = 0, amp = 0){ const p = geo.attributes.position; for (let i = 0; i < p.count; i++){ const x = p.getX(i), y = p.getY(i), z = p.getZ(i), a = Math.atan2(z, x) + y * k, r = Math.hypot(x, z) * (1 + amp * Math.sin(lobes * Math.atan2(z, x) + y * k * lobes)); p.setXYZ(i, Math.cos(a) * r * (lobes ? 1 : 1), y, Math.sin(a) * r); } geo.computeVertexNormals(); return geo; }
const glassShapes = [
  c => { const g = new THREE.Group(); add(g, lathe([[0, -1.25], [.35, -1.05], [.78, -.55], [.95, .05], [.8, .55], [.42, .95], [.2, 1.05]], 56), glass(c)); add(g, lathe([[0, -.9], [.3, -.7], [.5, -.2], [.4, .4], [.15, .7]], 32), glow(c, .35), 0, 0, 0); cap(g, 1.03, .8); return g; },
  c => { const g = new THREE.Group(); const geo = lathe([[.0, 1.05], [.5, 1.0], [.56, .7], [.46, .2], [.34, -.4], [.2, -1.0], [.07, -1.45], [0, -1.6]], 72, 60); const p = geo.attributes.position; for (let i = 0; i < p.count; i++){ const x = p.getX(i), y = p.getY(i), z = p.getZ(i), a = Math.atan2(z, x), r = Math.hypot(x, z) * (1 + .16 * Math.cos(5 * a + y * 6)); p.setXYZ(i, Math.cos(a) * r, y, Math.sin(a) * r); } geo.computeVertexNormals(); add(g, geo, glass(c)); add(g, lathe([[0, .9], [.18, .6], [.12, -.4], [0, -1.2]], 24, 20), glow(c, .45)); cap(g, 1.02, .7); return g; },
  c => { const g = new THREE.Group(); add(g, lathe([[0, -1.3], [.08, -1.15], [.5, -.75], [.95, -.15], [.92, .25], [.55, .7], [.2, 1.0], [.12, 1.08]], 56), glass(c)); add(g, tor(.94, .08, 10, 56), GOLD(), 0, .05, 0, Math.PI / 2); add(g, tor(.6, .05, 8, 40), GOLD(), 0, .62, 0, Math.PI / 2); add(g, sph(.12, 12, 8), GOLD(), 0, -1.3); cap(g, 1.05, .7); return g; },
  c => { const g = new THREE.Group(); const geo = new THREE.OctahedronGeometry(1, 0); geo.scale(.85, 1.3, .85); const m = new THREE.MeshPhysicalMaterial({ color:c, roughness:.04, metalness:.1, transparent:true, opacity:.8, clearcoat:1, flatShading:true, side:THREE.DoubleSide }); add(g, geo, m); add(g, new THREE.OctahedronGeometry(.55, 0), glow(c, .4), 0, 0, 0, 0, .4, 0, .8, 1.2, .8); cap(g, 1.28, .6); return g; },
  c => { const g = new THREE.Group(); const geo = lathe([[0, 1.0], [.85, .92], [1.0, .6], [.82, .05], [.56, -.5], [.32, -1.0], [.1, -1.4], [0, -1.5]], 96, 80); const p = geo.attributes.position; for (let i = 0; i < p.count; i++){ const x = p.getX(i), y = p.getY(i), z = p.getZ(i), a = Math.atan2(z, x), r = Math.hypot(x, z), ph = a + y * 5.5, f = 1 + .11 * Math.pow(.5 + .5 * Math.cos(ph), 3) - .04; p.setXYZ(i, Math.cos(a) * r * f, y, Math.sin(a) * r * f); } geo.computeVertexNormals(); add(g, geo, glass(c)); add(g, lathe([[0, .7], [.3, .5], [.2, -.4], [0, -1.1]], 24, 20), glow(c, .4)); cap(g, 1.0, .75); return g; },
];

/* ---------- フェルトの動物 ---------- */
function feltHead(main, opt = {}){ const g = new THREE.Group(); add(g, sph(1, 40, 28), felt(main), 0, 0, 0, 0, 0, 0, 1, .96, .92); if (!opt.noEyes){ eye(g, -.36, .1, .8, opt.eyeR || .1); eye(g, .36, .1, .8, opt.eyeR || .1); } if (!opt.noCheek){ cheek(g, -.6, -.2, .7); cheek(g, .6, -.2, .7); }
  // 赤いマフラー
  add(g, tor(.78, .2, 12, 40), felt('#d8403a'), 0, -.78, 0, Math.PI / 2 - .15, 0, 0, 1, 1, .7); add(g, rbox(.32, .6, .14, .06), felt('#d8403a'), .45, -1.05, .55, 0, 0, .3);
  for (let i = 0; i < 3; i++) add(g, rbox(.33, .06, .02), felt('#f6f0e4'), .45 + i * .03, -.98 - i * .14, .63, 0, 0, .3); thread(g, .95); return g; }
const muzzle = (g, c, nose = '#3a2416', y = -.22, s = 1) => { add(g, sph(.42 * s, 24, 16), felt(c), 0, y, .78, 0, 0, 0, 1, .75, .55); add(g, sph(.13 * s, 16, 10), BLACK(), 0, y + .08, 1.0, 0, 0, 0, 1.2, .9, .8); add(g, tube([[-.1, y - .12, .97], [0, y - .17, .99], [.1, y - .12, .97]], .02, 12), BLACK()); };
