/* ---------- 一覧 ---------- */
const BUILD = {
  red:() => ball('#c8202a'), gold:() => ball('#f6c85a', null, { metal:true }), silver:() => ball('#eef1f6', null, { metal:true }), blue:() => ball('#3a6ab8', null, { glass:true }), green:() => ball('#2f7a4a', sphereDots('#2f7a4a', '#f6e08a', 6)), pinkst:() => ball('#f2a6be', sphereBands('#f2a6be', '#ffffff', 7)),
  glassheart:() => { const g = new THREE.Group(); add(g, ext(shHeart(1.0), .4, .16, 4), glass('#f48aa8')); add(g, ext(shHeart(.55), .2, .08), glow('#f48aa8', .3)); cap(g, .55, .75); g.userData.hangY = 1.05; return g; },
};
for (let j = 0; j < 5; j++) BC.forEach(([, c], i) => BUILD[`b${j}${i}`] = () => ballPat[j](c));
for (let j = 0; j < 5; j++) GC.forEach((c, i) => BUILD[`g${j}${i}`] = () => glassShapes[j](c));
ANIMALS.forEach(([, f], i) => BUILD['f' + i] = f);
[...SWEETS, ...CLASSIC, ...WINTER, ...SKY, ...PAIR].forEach(([k, f]) => BUILD[k] = f);
export const KEYS = Object.keys(BUILD);

/* 大きさをそろえる：高さ 0.27 / 幅 0.25 に収め、吊り下げ点が y=+0.13 */
export function makeOrnament(key){
  const f = BUILD[key] || BUILD.red, raw = f(); const box = new THREE.Box3().setFromObject(raw), size = box.getSize(V(0, 0, 0));
  const s = Math.min(.27 / size.y, .25 / size.x, .25 / Math.max(.01, size.z * .9)); const out = new THREE.Group(); raw.scale.multiplyScalar(s);
  const top = raw.userData.hangY != null ? raw.userData.hangY * s : box.max.y * s; const cx = (box.min.x + box.max.x) / 2 * s, cz = (box.min.z + box.max.z) / 2 * s;
  raw.position.set(raw.position.x * s - cx, .13 - top, raw.position.z * s - cz); out.add(raw); out.traverse(m => { if (m.isMesh){ m.castShadow = true; } }); out.userData.key = key; return out;
}

/* ---------- 図鑑用のサムネイル（3Dを画像にする） ---------- */
let TR = null; const thumbs = new Map();
function thumbRig(){ if (TR) return TR; const r = new THREE.WebGLRenderer({ antialias:true, alpha:true, preserveDrawingBuffer:true }); r.setPixelRatio(1); r.setSize(192, 192); r.outputColorSpace = THREE.SRGBColorSpace; r.toneMapping = THREE.NeutralToneMapping; r.setClearColor(0x000000, 0);
  const sc = new THREE.Scene(), pm = new THREE.PMREMGenerator(r); sc.environment = pm.fromScene(new RoomEnvironment(), .04).texture; sc.environmentIntensity = .45;
  sc.add(new THREE.HemisphereLight('#fff1dc', '#b98a6a', 1.2)); const d = new THREE.DirectionalLight('#ffe8c8', 2.2); d.position.set(-2, 3, 4); sc.add(d); const d2 = new THREE.DirectionalLight('#c8dcff', .6); d2.position.set(3, 1, -2); sc.add(d2);
  const cam = new THREE.PerspectiveCamera(22, 1, .1, 10); cam.position.set(0, .05, .95); cam.lookAt(0, -.005, 0); TR = { r, sc, cam }; return TR; }
export function thumb(key){ if (thumbs.has(key)) return thumbs.get(key); const { r, sc, cam } = thumbRig(); const o = makeOrnament(key); o.position.y = -.005; o.rotation.y = -.25; sc.add(o); r.render(sc, cam); const url = r.domElement.toDataURL('image/png'); sc.remove(o); o.traverse(m => { if (m.isMesh) m.geometry.dispose(); }); thumbs.set(key, url); return url; }

/* 部屋の家具・飾り用：吊り金具なしで作り、高さ h にして底を y=0 に置く */
export function makeDeco(key, h, arg){
  NOHANG = true; let raw; try { raw = arg !== undefined && BUILD[key] ? BUILD[key](arg) : (BUILD[key] || BUILD.red)(); } finally { NOHANG = false; }
  raw.rotation.set(0, 0, 0); const box = new THREE.Box3().setFromObject(raw), size = box.getSize(V(0, 0, 0)), s = h / size.y; raw.scale.multiplyScalar(s);
  const b2 = new THREE.Box3().setFromObject(raw), c = b2.getCenter(V(0, 0, 0)); raw.position.sub(V(c.x, b2.min.y, c.z));
  const out = new THREE.Group(); out.add(raw); out.traverse(m => { if (m.isMesh){ m.castShadow = true; m.receiveShadow = true; } }); return out;
}
